"""Use actual engine shader/image layouts to verify conservative material batching."""
from pathlib import Path
import argparse, subprocess, tempfile
p=argparse.ArgumentParser();p.add_argument('--engine',type=Path,required=True);p.add_argument('--compiler',default='cc');a=p.parse_args()
s=(a.engine/'client/pr_csqc.c').read_text();helper=s[s.index('// Equivalent failed-image materials'):s.index('// ReyondBroom native face pass begin.')]
prefix='#define CLIENTONLY\n#define GLQUAKE\n#include "quakedef.h"\n#include "glquake.h"\n#include "shader.h"\n#include <assert.h>\nfloat Cvar_VariableValue(const char *name){(void)name;return 1;}\n'
checks='int main(void){\n shader_t a={0},b={0};texnums_t ta={0},tb={0};image_t ia={0},ib={0};\n strcpy(a.name,"ftebroom/opaque/a");strcpy(b.name,"ftebroom/opaque/b");a.numpasses=b.numpasses=1;a.sort=b.sort=SHADER_SORT_OPAQUE;a.remapto=&a;b.remapto=&b;a.defaulttextures=&ta;b.defaulttextures=&tb;\n a.passes[0].texgen=b.passes[0].texgen=T_GEN_SINGLEMAP;a.passes[0].tcgen=b.passes[0].tcgen=TC_GEN_BASE;a.passes[0].rgbgen=b.passes[0].rgbgen=RGB_GEN_VERTEX_EXACT;\n ia.status=ib.status=TEX_FAILED;a.passes[0].anim_frames[0]=&ia;b.passes[0].anim_frames[0]=&ib;\n RB_MissingBegin(30000);assert(RB_CanonicalMissing(&a)==&a);assert(RB_CanonicalMissing(&b)==&a);\n RB_MissingBegin(1);assert(RB_CanonicalMissing(&a)==&a&&RB_CanonicalMissing(&b)==&b);\n RB_MissingBegin(30000);ib.status=TEX_LOADED;assert(RB_CanonicalMissing(&a)==&a&&RB_CanonicalMissing(&b)==&b);ib.status=TEX_FAILED;\n b.flags=SHADER_BLEND;assert(!RB_MissingEligible(&b));b.flags=0;\n b.passes[0].numtcmods=1;assert(!RB_MissingEligible(&b));b.passes[0].numtcmods=0;\n b.passes[0].anim_numframes=2;assert(!RB_MissingEligible(&b));b.passes[0].anim_numframes=0;\n ib.num=123;assert(!RB_SameMissingShader(&a,&b));ib.num=0;\n b.passes[0].shaderbits=1;assert(!RB_SameMissingShader(&a,&b));b.passes[0].shaderbits=0;\n b.factors[0][0]=1;assert(!RB_SameMissingShader(&a,&b));b.factors[0][0]=0;\n b.prog=(void*)1;assert(!RB_SameMissingShader(&a,&b));b.prog=NULL;\n RB_MissingBegin(30000);a.passes[0].anim_frames[0]=b.passes[0].anim_frames[0]=&ia;ia.status=TEX_LOADED;assert(RB_CanonicalMissing(&a)==&a&&RB_CanonicalMissing(&b)==&a);\n puts("PASS: zero-frame singlemap binding, failed/shared-image equivalence, distinct loaded textures, blending, animation, shader state, factors, program and small-map exclusion");\n}\n'
with tempfile.TemporaryDirectory() as directory:
 file=Path(directory)/'test.c';exe=Path(directory)/'test.exe';file.write_text(prefix+helper+checks)
 includes=[a.engine,a.engine/'client',a.engine/'common',a.engine/'gl',a.engine/'server',a.engine/'qclib']
 subprocess.run([a.compiler,'-std=gnu99','-O2',*['-I'+str(p.resolve()) for p in includes],str(file),'-o',str(exe)],check=True)
 subprocess.run([str(exe)],check=True)
